import{it as e,n as t,rt as n,vt as r}from"./chunks/framework.BQh0MzVE.js";var i=JSON.parse(`{"title":"Reload","description":"","frontmatter":{},"headers":[],"relativePath":"pages/config/reload.md","filePath":"pages/config/reload.md"}`),a={name:`pages/config/reload.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="reload" tabindex="-1">Reload <a class="header-anchor" href="#reload" aria-label="Permalink to “Reload”">​</a></h1><p>To update the configuration of the exporter without restarting it, you may want to use the reload feature. This allows to apply changes to the configuration file dynamically, discovering new collectors or updating existing ones without downtime.</p><p>To enable reloading we have to pass the <code>--web.enable-reload</code> flag to the exporter command line. This will enable the reload feature and expose an <code>/reload</code> HTTP endpoint or let send a SIGHUP signal to the exporter process to trigger a reload.</p><p>What&#39;s allowed to be reloaded:</p><ul><li>global settings;</li><li>collector settings (e.g. metrics, queries, adding/removing collectors);</li></ul><p>What&#39;s not allowed to be reloaded and requires a restart:</p><ul><li>targets (connection strings);</li><li>switching modes (<code>target</code> vs. <code>jobs</code>);</li></ul><p>It is important to note that connections will not be changed upon the restart of the exporter, so if you change the connection settings in the configuration file, you will need to restart the exporter for those changes to take effect. This is intended behavior to avoid unnecessary connection churn and to maintain the state of the monitored services. Security aspect is another reason as we don&#39;t want hijacked connections that might end up contributing to a (Distributed) Denial of Service or any other malicious activity.</p>`,8)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};